/// ai-agent-builder: Builder with a test chat
private struct AiAgentBuilderExample0: View {
    @Environment(\.monarchTheme) private var theme

    private struct EchoTransport: MonarchAiTransport {
        func stream(_ request: MonarchAiTransportRequest) -> MonarchAiEventStream {
            MonarchAiEventStream { continuation in
                continuation.yield(.textDelta("The agent received: " + (request.messages.last?.text ?? "")))
                continuation.yield(.done())
                continuation.finish()
            }
        }
    }

    /// A send the conversation refused, so the prompt input gives the text back.
    private struct NotSent: Error {}

    private let maxInstructions = 8000

    /// The tool the definition lists is allowed; the others are never run (the web shows plain checkboxes).
    private static func toolPermission(_ selected: String, _ id: String) -> MonarchAiConnectorToolPermission {
        id == selected ? .allow : .never
    }
    private let sources = [
        MonarchAiKnowledgeSource(
            id: "handbook",
            label: "Team handbook",
            kind: .space,
            children: [
                MonarchAiKnowledgeSource(id: "onboarding", label: "Onboarding guide", kind: .document),
                MonarchAiKnowledgeSource(id: "policies", label: "Policies", kind: .document),
            ]
        ),
        MonarchAiKnowledgeSource(id: "tickets", label: "Support tickets", kind: .app),
    ]

    @State private var name = "Onboarding guide"
    @State private var role = "Helps new teammates find answers"
    @State private var instructions = "Answer from the team handbook. Keep answers short and link the source."
    @State private var knowledge = ["handbook"]
    @State private var connectors = [
        MonarchAiConnector(
            id: "docs",
            name: "Documents",
            status: .connected,
            isEnabled: true,
            tools: [
                MonarchAiConnectorTool(id: "search", name: "Search documents", description: "Reads documents the agent can see.", risk: .read, permission: Self.toolPermission("search", "search")),
                MonarchAiConnectorTool(id: "tasks", name: "Create tasks", description: "Asks before creating anything.", risk: .write, permission: Self.toolPermission("search", "tasks")),
                MonarchAiConnectorTool(id: "email", name: "Draft email", description: "Drafts only; never sends.", risk: .write, permission: Self.toolPermission("search", "email")),
            ]
        )
    ]
    @State private var triedSave = false
    @State private var saved = false
    @State private var prompt = ""
    // The test chat runs the unsaved definition: the transport reads it from the request body.
    @State private var conversation = MonarchAiConversation(transport: EchoTransport())

    private var agent: MonarchAiAgentRef {
        MonarchAiAgentRef(name: name.isEmpty ? "New agent" : name, role: role.isEmpty ? nil : role)
    }

    private var nameError: String? {
        triedSave && name.trimmingCharacters(in: .whitespaces).isEmpty ? "Give the agent a name." : nil
    }

    /// The tools the agent may use: those of enabled connectors that are not set to Never.
    private var toolIDs: [String] {
        connectors.filter(\.isEnabled).flatMap { connector in
            connector.tools.filter { $0.permission != .never }.map(\.id)
        }
    }

    private var definition: MonarchAiJSON {
        .object([
            "name": .string(name),
            "role": .string(role),
            "instructions": .string(instructions),
            "tools": .array(toolIDs.map { .string($0) }),
            "knowledge": .array(knowledge.map { .string($0) }),
        ])
    }

    private var form: some View {
        Form {
            Section {
                // The avatar sits left of the two fields, as on the web, and the Role helper above its field.
                HStack(alignment: .top, spacing: theme.spacing.space3) {
                    MonarchAiAgentAvatar(agent, size: .lg, isDecorative: true)
                    VStack(alignment: .leading, spacing: theme.spacing.space3) {
                        MonarchTextField("Name", text: $name, error: nameError, isRequired: true)
                        MonarchTextField("Role", text: $role, helper: "One line shown under the name, e.g. “Support assistant”.")
                    }
                    .monarchHelperAbove()
                }
            } header: {
                sectionTitle("Persona")
            }
            Section {
                TextField("Instructions", text: $instructions, axis: .vertical)
                    .lineLimit(4...12)
                    .monarchTextStyle(.body)
            } header: {
                sectionTitle("Instructions")
            } footer: {
                Text("\(instructions.count) / \(maxInstructions) characters")
            }
            Section {
                ForEach(connectors.first?.tools ?? [], id: \.id) { tool in
                    Toggle(isOn: toolBinding(tool.id)) {
                        VStack(alignment: .leading, spacing: theme.spacing.space1) {
                            Text(tool.name).monarchTextStyle(.body)
                            if let description = tool.description {
                                Text(description)
                                    .monarchTextStyle(.caption)
                                    .foregroundStyle(theme.colors.textMuted)
                            }
                        }
                    }
                    .toggleStyle(.monarchCheckbox)
                }
            } header: {
                VStack(alignment: .leading, spacing: theme.spacing.space1) {
                    sectionTitle("Tools")
                    Text("Actions the agent may take. It asks before running anything that changes data.")
                        .monarchTextStyle(.caption)
                        .textCase(nil)
                }
            }
            Section {
                MonarchAiKnowledgeScope(sources, selection: $knowledge, startsExpanded: [])
            } header: {
                sectionTitle("Knowledge")
            }
            Section {
                MonarchButton("Save agent", variant: .primary) {
                    let isNamed = !name.trimmingCharacters(in: .whitespaces).isEmpty
                    triedSave = true
                    // The app saves definition on its server here.
                    saved = isNamed
                    if isNamed { AccessibilityNotification.Announcement("Agent saved.").post() }
                }
                .frame(maxWidth: .infinity, alignment: .trailing)
                .listRowBackground(Color.clear)
            } footer: {
                if saved { Text("Agent saved.") }
            }
            Section {
                test
                    .overlay(
                        RoundedRectangle(cornerRadius: theme.radius.lg).strokeBorder(theme.colors.aiBorder, lineWidth: 1)
                    )
                    .listRowInsets(EdgeInsets())
            }
        }
        .onChange(of: instructions) { _, text in
            if text.count > maxInstructions { instructions = String(text.prefix(maxInstructions)) }
        }
        .onChange(of: definition) { saved = false }
    }

    private func sectionTitle(_ text: String) -> some View {
        Text(text)
            .monarchTextStyle(.bodyStrong)
            .foregroundStyle(theme.colors.textDefault)
            .textCase(nil)
            .accessibilityAddTraits(.isHeader)
    }

    private func toolBinding(_ id: String) -> Binding<Bool> {
        Binding(
            get: { connectors.first?.tools.first { $0.id == id }?.permission == .allow },
            set: { isOn in
                guard let index = connectors.first?.tools.firstIndex(where: { $0.id == id }) else { return }
                connectors[0].tools[index].permission = isOn ? .allow : .never
            }
        )
    }

    private var test: some View {
        VStack(alignment: .leading, spacing: 0) {
            VStack(alignment: .leading, spacing: theme.spacing.space2) {
                HStack(spacing: theme.spacing.space2) {
                    MonarchAiAgentAvatar(agent, state: conversation.isBusy ? .working : .idle, size: .sm, isDecorative: true)
                    Text("Test")
                        .monarchTextStyle(.subheading)
                        .accessibilityAddTraits(.isHeader)
                        .frame(maxWidth: .infinity, alignment: .leading)
                    Button("Restart test") {
                        conversation.stop()
                        conversation.reset()
                    }
                    .buttonStyle(.monarch(.ghost, size: .sm))
                    .disabled(conversation.messages.isEmpty)
                }
                Text("Try the agent with the current settings. Nothing here is saved.")
                    .monarchTextStyle(.caption)
                    .foregroundStyle(theme.colors.textMuted)
            }
            .padding(theme.spacing.space4)
            MonarchAiThread(
                conversation.messages,
                status: conversation.status,
                error: conversation.error,
                showsDaySeparators: false,
                onStop: { conversation.stop() },
                empty: {
                    Text("Send a message to try the agent.")
                        .monarchTextStyle(.body)
                        .foregroundStyle(theme.colors.textMuted)
                }
            )
            .frame(height: 160)
            MonarchAiPromptInput(
                "Message the agent",
                text: $prompt,
                isBusy: conversation.isBusy,
                onStop: { conversation.stop() },
                onSubmit: { text in
                    guard conversation.send(text, body: ["agent": definition]) else { throw NotSent() }
                }
            )
            .padding(theme.spacing.space4)
        }
    }

    var body: some View {
        NavigationStack {
            // One column, as the web draws it: the form, then the Test panel below it.
            form
                .monarchCanvas()
                #if os(iOS)
                    .toolbar(.hidden, for: .navigationBar)
                #endif
        }
    }
}

