/// ai-assistant-panel: A pane beside the content, with plain state
private struct AiAssistantPanelExample1: View {
    @Environment(\.monarchTheme) private var theme
    @State private var messages: [MonarchAiConversationMessage] = []
    @State private var isOpen = true

    var body: some View {
        MonarchAiAssistantPanel(
            "Assistant",
            messages: messages,
            isPresented: $isOpen,
            placement: .inline,
            agent: MonarchAiAgentRef(name: "Dossier", role: "Workspace assistant"),
            onSend: { text in
                // With a MonarchAiConversation, use the initialiser that takes it instead.
                messages.append(
                    MonarchAiConversationMessage(
                        id: "u\(messages.count)",
                        role: .user,
                        parts: [.text(MonarchAiTextPart(text: text))],
                        createdAt: MonarchAiConversationMessage.timestamp(.now)
                    )
                )
            }
        )
