/// ai-settings-section: Workspace AI settings
private struct AiSettingsSectionExample0: View {
    @State private var apps: [String: Bool] = [
        "docs": true,
        "mail": false,
        "calendar": true,
    ]
    @State private var savedApps: [String: Bool] = [
        "docs": true,
        "mail": false,
        "calendar": true,
    ]
    @State private var sharing = false
    @State private var savedSharing = false
    @State private var memory = true
    @State private var savedMemory = true
    @State private var retention = "90d"
    @State private var savedRetention = "90d"
    @State private var provider = ""
    @State private var savedProvider = ""

    private var isDirty: Bool {
        apps != savedApps || sharing != savedSharing || memory != savedMemory
            || retention != savedRetention || provider != savedProvider
    }

    private func binding(for app: String) -> Binding<Bool> {
        Binding(
            get: { apps[app] ?? false },
            set: { apps[app] = $0 }
        )
    }

    var body: some View {
        MonarchSectionCard(
            "AI",
            description: "Choose where AI is available in this workspace and how it handles your data.",
            systemImage: "cpu"
        ) {
            VStack(alignment: .leading, spacing: 16) {
                Text("Use AI in")
                    .monarchTextStyle(.label)
                Text("Turn AI features on or off for each app.")
                    .monarchTextStyle(.caption)
                VStack(alignment: .leading) {
                    Toggle("Documents", isOn: binding(for: "docs"))
                    Text("Summaries, drafts and answers about pages.")
                        .monarchTextStyle(.caption)
                }
                VStack(alignment: .leading) {
                    Toggle("Mail", isOn: binding(for: "mail"))
                    Text("Reply suggestions and thread summaries.")
                        .monarchTextStyle(.caption)
                }
                Toggle("Calendar", isOn: binding(for: "calendar"))
                VStack(alignment: .leading) {
                    Toggle("Share data to improve AI", isOn: $sharing)
                    Text("Allow prompts and responses to be used to improve AI quality. Off keeps them private to this workspace.")
                        .monarchTextStyle(.caption)
                }
                VStack(alignment: .leading) {
                    Toggle("Memory", isOn: $memory)
                    Text("Let AI remember facts and preferences across conversations.")
                        .monarchTextStyle(.caption)
                }
                MonarchSelectField(
                    "Conversation history",
                    selection: $retention,
                    options: [
                        MonarchSelectOption("30 days", value: "30d"),
                        MonarchSelectOption("90 days", value: "90d"),
                        MonarchSelectOption("1 year", value: "1y"),
                        MonarchSelectOption("Until deleted", value: "forever"),
                    ],
                    helper: "How long AI conversations are kept before they are deleted."
                )
                MonarchSelectField(
                    "AI provider",
                    selection: $provider,
                    options: [
                        MonarchSelectOption("Built-in", value: ""),
                        MonarchSelectOption("Provider A", value: "provider-a"),
                        MonarchSelectOption("Provider B", value: "provider-b"),
                    ],
                    helper: "Use the built-in provider or bring your own key."
                )
            }
        } footer: {
            HStack {
                Spacer()
                MonarchButton("Discard") {
                    apps = savedApps
                    sharing = savedSharing
                    memory = savedMemory
                    retention = savedRetention
                    provider = savedProvider
                }
                .disabled(!isDirty)
                MonarchButton("Save changes", variant: .primary) {
                    // The app saves the draft here.
                    savedApps = apps
                    savedSharing = sharing
                    savedMemory = memory
                    savedRetention = retention
                    savedProvider = provider
                }
                .disabled(!isDirty)
            }
        }
    }
}

