                MonarchAiTraceSpan(id: "analysis-model", parentId: "analysis", kind: .model, name: "Write the summary", status: .ok, start: 2900 / 1000, end: 6100 / 1000, inputTokens: 4200, outputTokens: 910, costMicros: 9800),
            ],
            currency: "EUR"
        )
        .environment(\.locale, Locale(identifier: "en-GB"))
    }
}

/// ai-trace-view: Errors only, with a running span
private struct AiTraceViewExample1: View {
    @State private var filter = MonarchAiTraceFilter.errors

    var body: some View {
        MonarchAiTraceView(
            [
                MonarchAiTraceSpan(id: "run", kind: .agent, name: "Answer question", status: .running, start: 0),
                MonarchAiTraceSpan(id: "check", parentId: "run", kind: .guardrail, name: "Safety check", status: .error, start: 0.5, end: 0.7),
            ],
            now: 2,
            filter: $filter
        )
    }
}

/// ai-voice-input: Scripted demo (works without a microphone)
private struct AiVoiceInputExample0: View {
    @State private var prompt = ""

    var body: some View {
        VStack(alignment: .leading) {
            MonarchTextField("Prompt", text: $prompt, axis: .vertical, lineLimit: 3...3, labelVisibility: .hidden)
            MonarchAiVoiceInput(
                showsLevel: false,
                labels: MonarchAiVoiceInputLabels(dictate: "Dictate")
            ) { text, isFinal in
                if isFinal { prompt += (prompt.isEmpty ? "" : " ") + text }
            }
        }
    }
}

/// ai-voice-input: Hold to talk, on the device only
private struct AiVoiceInputExample1: View {
    var body: some View {
        MonarchAiVoiceInput(
            mode: .pushToTalk,
            size: .sm,
            recognizer: MonarchAiSystemSpeechRecognizer(prefersOnDeviceRecognition: true)
        ) { _, _ in }
    }
}
